const NAV = [
  { id: "home", label: "בית" },
  { id: "portfolio", label: "עבודות" },
  { id: "pricing", label: "חבילות" },
  { id: "booking", label: "הזמן" },
  { id: "charter", label: "תקנון" },
  { id: "about", label: "אודות" },
  { id: "agents", label: "Agents AI" },
];

/* ═══════════════════════════════════
   APP
═══════════════════════════════════ */
export default function VisioApp() {
  const [page, setPage] = useState("home");
  const [menuOpen, setMenuOpen] = useState(false);

  const nav = (p) => { setPage(p); setMenuOpen(false); window.scrollTo(0, 0); };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Heebo:wght@300;400;500&display=swap');
        *, *::before, *::after { box-sizing: border-box; }
        body { margin: 0; background: #060606; color: #e8dfc8; font-family: 'Heebo', sans-serif; }
        input, select, textarea, button { font-family: 'Heebo', sans-serif; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: #060606; }
        ::-webkit-scrollbar-thumb { background: #1e1c14; }
        button:hover { opacity: 0.85; }
        @keyframes fadein { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} }
        .page-content { animation: fadein 0.3s ease; }
      `}</style>

      {/* ── NAVBAR ── */}
      <nav style={{ position: "sticky", top: 0, zIndex: 100, background: "rgba(6,6,4,.96)", borderBottom: `1px solid ${C.border}`, backdropFilter: "blur(12px)" }}>
        <div style={{ maxWidth: 1200, margin: "0 auto", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 20px", height: 56, direction: "rtl" }}>

          {/* Logo */}
          <button onClick={() => nav("home")} style={{ display: "flex", alignItems: "center", gap: 10, background: "none", border: "none", cursor: "pointer", padding: 0 }}>
            <VisioMark size={32} />
            <span style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 20, letterSpacing: 6, color: C.gold }}>VISIO</span>
          </button>

          {/* Desktop nav */}
          <div style={{ display: "flex", gap: 0 }}>
            {NAV.map(n => (
              <button key={n.id} onClick={() => nav(n.id)}
                style={{ padding: "0 14px", height: 56, background: "none", border: "none", fontFamily: "'Bebas Neue', sans-serif", fontSize: 11, letterSpacing: 3, color: page === n.id ? C.gold : C.muted, cursor: "pointer", borderBottom: page === n.id ? `2px solid ${C.gold}` : "2px solid transparent", marginBottom: -1, whiteSpace: "nowrap" }}>
                {n.label}
              </button>
            ))}
          </div>

          {/* CTA */}
          <button onClick={() => nav("booking")} style={{ padding: "8px 20px", background: `linear-gradient(135deg,${C.gold},${C.goldDim})`, border: "none", fontFamily: "'Bebas Neue', sans-serif", fontSize: 11, letterSpacing: 3, color: C.bg, cursor: "pointer" }}>
            הזמן
          </button>
        </div>
      </nav>

      {/* ── CONTENT ── */}
      <main style={{ maxWidth: 1200, margin: "0 auto" }} className="page-content" key={page}>
        {page === "home" && <HomeSection onNav={nav} />}
        {page === "portfolio" && <PortfolioSection />}
        {page === "pricing" && <PricingSection onBook={() => nav("booking")} />}
        {page === "booking" && <BookingSection />}
        {page === "charter" && <CharterSection />}
        {page === "about" && <AboutSection onNav={nav} />}
        {page === "agents" && <AgentsSection />}
      </main>

      {/* ── FOOTER ── */}
      <footer style={{ borderTop: `1px solid ${C.border}`, padding: "24px 20px", textAlign: "center", direction: "rtl", marginTop: 40 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 12, marginBottom: 12 }}>
          <VisioMark size={28} />
          <span style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: 16, letterSpacing: 5, color: C.gold }}>VISIO</span>
        </div>
        <p style={{ fontSize: 11, color: "#2a2820", letterSpacing: 2, margin: "0 0 12px" }}>נדל״ן. בצילום שמוכר. · כל הזכויות שמורות © 2025</p>
        <div style={{ display: "flex", gap: 20, justifyContent: "center", flexWrap: "wrap" }}>
          {NAV.map(n => (
            <button key={n.id} onClick={() => nav(n.id)} style={{ background: "none", border: "none", fontFamily: "'Bebas Neue', sans-serif", fontSize: 10, letterSpacing: 3, color: "#2a2820", cursor: "pointer" }}>
              {n.label}
            </button>
          ))}
        </div>
      </footer>
    </>
  );
}
